+@page "/board"
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h3 class="mb-3">Project Board</h3>
+
+@if (loading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+else
+{
+    <BoardStats Tasks="allTasks" />
+    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="HandleSearchChanged" />
+
+    <div class="row g-3">
+        <KanbanColumn ColumnName="To Do"
+                      Tasks="FilteredByColumn(\"To Do\")"
+                      ShowMoveLeft="false"
+                      ShowMoveRight="true"
+                      OnMoveRight="@(id => MoveTask(id, \"In Progress\"))"
+                      OnAddTask="@(form => AddTask(form, \"To Do\"))" />
+
+        <KanbanColumn ColumnName="In Progress"
+                      Tasks="FilteredByColumn(\"In Progress\")"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="true"
+                      OnMoveLeft="@(id => MoveTask(id, \"To Do\"))"
+                      OnMoveRight="@(id => MoveTask(id, \"Done\"))"
+                      OnAddTask="@(form => AddTask(form, \"In Progress\"))" />
+
+        <KanbanColumn ColumnName="Done"
+                      Tasks="FilteredByColumn(\"Done\")"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="false"
+                      OnMoveLeft="@(id => MoveTask(id, \"In Progress\"))"
+                      OnAddTask="@(form => AddTask(form, \"Done\"))" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private string searchTerm = "";
+    private bool loading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            loading = false;
+        }
+    }
+
+    private List<TaskItem> FilteredByColumn(string status)
+    {
+        var tasks = allTasks.Where(t => t.Status == status);
+        if (!string.IsNullOrWhiteSpace(searchTerm))
+        {
+            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
+        }
+        return tasks.ToList();
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchTerm = value;
+    }
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = allTasks.First(t => t.Id == taskId);
+            allTasks = allTasks.Select(t => t.Id == taskId ? task with { Status = newStatus } : t).ToList();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) form, string status)
+    {
+        try
+        {
+            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
+            allTasks.Add(newTask with { Status = status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
+

